### 8. **No CORS Configuration (MEDIUM)**

**Issue:** No CORS headers configured, which can lead to unauthorized cross-origin requests.

**Recommended Fix:**
```javascript
const cors = require('cors'); // Install: npm install cors

// Whitelist allowed origins
const allowedOrigins = [
  'https://yourdomain.com',
  'https://app.yourdomain.com'
];

const corsOptions = {
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};

app.use(cors(corsOptions));

// Or configure per route
app.get('/public-data', cors(), (req, res) => {
  res.json({ data: 'public' });
});
```

