const securityMiddleware = (req, res, next) => {
  // Detect common attack patterns
  const attackPatterns = {
    sqlInjection: /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|UNION|EXEC)\b)/i,
    xss: /(<script|javascript:|on\w+\s*=)/i,
    pathTraversal: /\.\.[\/\\]/,
    commandInjection: /[;&|`$()]/,
    ldapInjection: /[()=*%&|]/i
  };

  const checkString = `${req.url}${JSON.stringify(req.query)}${JSON.stringify(req.body)}`;

  for (const [attackType, pattern] of Object.entries(attackPatterns)) {
    if (pattern.test(checkString)) {
      console.warn(`Security Alert: ${attackType} detected from ${req.ip}`);
      // Consider: block IP, notify security team, etc.
      if (process.env.BLOCK_ATTACKS === 'true') {
        return res.status(403).json({ error: 'Request blocked' });
      }
    }
  }

  next();
};

app.use(securityMiddleware);
```

