const AWS = require('aws-sdk');
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

// Load secrets from AWS Secrets Manager
async function loadSecrets() {
  const client = new SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });

  try {
    const response = await client.getSecretValue({
      SecretId: process.env.SECRET_ARN || 'prod/app-secrets'
    });

    const secretString = response.SecretString;
    const secrets = JSON.parse(secretString);

    // Merge secrets into process.env
    Object.assign(process.env, secrets);

    return secrets;
  } catch (error) {
    if (error.code === 'ResourceNotFoundException') {
      console.warn('Secret not found in AWS Secrets Manager, falling back to env vars');
    } else {
      console.error('Error loading secrets from AWS:', error);
      throw error;
    }
  }
}

// Load secrets before starting server
async function startServer() {
  await loadSecrets();

  // Validate required secrets
  if (!process.env.JWT_SECRET) {
    throw new Error('JWT_SECRET not configured');
  }

  const express = require('express');
  const app = express();

  // ... rest of app configuration

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

startServer().catch(error => {
  console.error('Failed to start server:', error);
  process.exit(1);
});
```

