/**
 * Secure Secrets Management Module
 * Implements defense-in-depth for secrets handling
 */

const dotenv = require('dotenv');
const fs = require('fs');
const path = require('path');

// Load environment-specific .env file
const env = process.env.NODE_ENV || 'development';

// Priority order for .env files (highest to lowest):
// 1. .env.local (never committed)
// 2. .env.{env} (environment-specific)
// 3. .env (default, base configuration)

function loadEnvFiles() {
  const envFiles = [
    `.env.${env}.local`,  // Environment-specific local overrides
    `.env.local`,         // Local overrides
    `.env.${env}`,        // Environment-specific
    '.env'                // Default/base configuration
  ];

  envFiles.forEach(file => {
    const filePath = path.resolve(process.cwd(), file);
    if (fs.existsSync(filePath)) {
      // Check file permissions (should be 600 or 400)
      const stats = fs.statSync(filePath);
      const mode = (stats.mode & parseInt('777', 8)).toString(8);

      // Warn if file is too permissive
      if (mode !== '600' && mode !== '400') {
        console.warn(`⚠️  File ${file} has permissive permissions: ${mode}. Run: chmod 600 ${file}`);
      }

      dotenv.config({ path: filePath });
      console.log(`📄 Loaded environment from: ${file}`);
    }
  });
}

/**
 * Required secrets configuration
 * Defines which secrets are required for each environment
 */
const REQUIRED_SECRETS = {
  development: [
    // Optional in dev - can use defaults
  ],
  test: [
    'DATABASE_URL',
    'JWT_SECRET'
  ],
  staging: [
    'DATABASE_URL',
    'JWT_SECRET',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'LOGFIRE_TOKEN'
  ],  
  production: [
    'DATABASE_URL',
    'JWT_SECRET',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN'
  ]
};

/**
 * Secret configuration with SSM parameter paths
 * For AWS Secrets Manager / Parameter Store integration
 */
const SECRETS_MANAGER_CONFIG = {
  AWS: {
    parameterStore: {
      '/app/database/url': 'DATABASE_URL',
      '/app/jwt/secret': 'JWT_SECRET',
      '/app/aws/access-key-id': 'AWS_ACCESS_KEY_ID',
      '/app/aws/secret-access-key': 'AWS_SECRET_ACCESS_KEY',
      '/app/stripe/secret-key': 'STRIPE_SECRET_KEY',
      '/app/anthropic/api-key': 'ANTHROPIC_API_KEY',
      '/app/logfire/token': 'LOGFIRE_TOKEN'
    },
    secretsManager: {
      'prod/app/database': ['DATABASE_URL'],
      'prod/app/stripe': ['STRIPE_SECRET_KEY'],
      'prod/app/anthropic': ['ANTHROPIC_API_KEY']
    }
  }
};

/**
 * Load secrets from AWS Systems Manager Parameter Store
 */
async function loadFromParameterStore(ssmClient) {
  const config = SECRETS_MANAGER_CONFIG.AWS.parameterStore;

  for (const [parameterPath, envVar] of Object.entries(config)) {
    try {
      const result = await ssmClient.send(
        new (require('@aws-sdk/client-ssm')).GetParameterCommand({
          Name: parameterPath,
          WithDecryption: true
        })
      );

      if (result.Parameter && result.Parameter.Value) {
        process.env[envVar] = result.Parameter.Value;
      }
    } catch (error) {
      // Parameter not found or access denied - will fail validation if required
      console.warn(`⚠️  Could not load parameter: ${parameterPath}`);
    }
  }
}

/**
 * Load secrets from AWS Secrets Manager
 */
async function loadFromSecretsManager(smClient) {
  const config = SECRETS_MANAGER_CONFIG.AWS.secretsManager;

  for (const [secretId, envVars] of Object.entries(config)) {
    try {
      const result = await smClient.send(
        new (require('@aws-sdk/client-secrets-manager')).GetSecretValueCommand({
          SecretId: secretId
        })
      );

      const secretString = result.SecretString;
      if (secretString) {
        try {
          const secretData = JSON.parse(secretString);
          // Map values from JSON to env vars
          Object.entries(secretData).forEach(([key, value]) => {
            const matchingEnvVar = envVars.find(ev => ev.toLowerCase().includes(key.toLowerCase()));
            if (matchingEnvVar) {
              process.env[matchingEnvVar] = value;
            }
          });
        } catch {
          // Not JSON, assign directly to first env var
          if (envVars[0]) {
            process.env[envVars[0]] = secretString;
          }
        }
      }
    } catch (error) {
      console.warn(`⚠️  Could not load secret: ${secretId}`);
    }
  }
}

/**
 * Validate that all required secrets are present
 * @throws {Error} If any required secret is missing
 */
function validateSecrets() {
  const required = REQUIRED_SECRETS[env] || [];
  const missing = [];

  for (const secretName of required) {
    const value = process.env[secretName];
    if (!value || value.trim() === '' || value.includes('CANARY')) {
      missing.push(secretName);
    }
  }

  if (missing.length > 0) {
    throw new Error(
      `❌ Missing or invalid required secrets for environment '${env}': ${missing.join(', ')}`
    );
  }

  // Additional validation for secrets that shouldn't use placeholder values
  const suspiciousPatterns = [
    { pattern: /password|secret|key/i, forbidden: ['changeme', 'default', 'placeholder', 'canary'] }
  ];

  for (const [key, value] of Object.entries(process.env)) {
    if (value) {
