function detectCommittedSecrets() {
  const checkPatterns = [
    { pattern: /REDACTED_AWS_AKID|\bCANARY-/gi, name: 'AWS Canaries' },
    { pattern: /REDACTED_STRIPE_LIVE/i, name: 'Stripe Canaries' },
    { pattern: /REDACTED_ANTHROPIC_KEY/i, name: 'Anthropic Canaries' },
    { pattern: /postgres:\/\/.*:[^@]+@/gi, name: 'Database URLs' }
  ];

  const envFiles = ['.env', '.env.test', '.env.development', '.env.production'];
  let warnings = [];

  envFiles.forEach(file => {
    if (fs.existsSync(file)) {
      const content = fs.readFileSync(file, 'utf8');
      checkPatterns.forEach(({ pattern, name }) => {
        if (pattern.test(content)) {
          warnings.push(`File ${file} contains ${name}`);
