 */
async function initializeSecrets(options = {}) {
  const {
    useSsm = false,
    useSecretsManager = false,
    verbose = true
  } = options;

  if (verbose) {
    console.log(`🔐 Initializing secrets management for environment: ${env}`);
  }

  // Load .env files (lowest priority)
  loadEnvFiles();

  // Load from secrets manager (if configured and available)
  if (useSecretsManager && ['staging', 'production'].includes(env)) {
    try {
      const smClient = new (require('@aws-sdk/client-secrets-manager')).SecretsManagerClient({});
      await loadFromSecretsManager(smClient);
      if (verbose) console.log('🔒 Loaded secrets from AWS Secrets Manager');
    } catch (error) {
      console.warn('⚠️  AWS Secrets Manager unavailable');
    }
  }

  // Load from parameter store (if configured and available)
  if (useSsm && ['staging', 'production'].includes(env)) {
    try {
      const ssmClient = new (require('@aws-sdk/client-ssm')).SSMClient({});
      await loadFromParameterStore(ssmClient);
      if (verbose) console.log('🔒 Loaded secrets from AWS Parameter Store');
    } catch (error) {
      console.warn('⚠️  AWS Parameter Store unavailable');
    }
  }

  // Detect if secrets are committed
  detectCommittedSecrets();

  // Validate required secrets
  validateSecrets();

  // Log secure startup (don't log actual secret values)
  if (verbose) {
    console.log('🔓 Secrets initialized successfully');
  }
