#!/usr/bin/env node
/**
 * Secret Detection Scanner
 * Scans codebase for potential leaked secrets
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Patterns for detecting secrets
const SECRET_PATTERNS = [
  {
    name: 'AWS Access Key',
    pattern: /AKIA[0-9A-Z]{16}/g,
    severity: 'critical',
    description: 'AWS access key identifier'
  },
  {
    name: 'Database Connection String',
    pattern: /(?:postgres|mysql|mongodb):\/\/[^:]+:[^@]+@/gi,
    severity: 'critical',
    description: 'Database URL with embedded credentials'
  },
  {
    name: 'Stripe Secret Key',
    pattern: /sk_live_[0-9a-zA-Z]{24,}/g,
    severity: 'critical',
    description: 'Stripe live secret key'
  },
  {
    name: 'Stripe Test Key',
    pattern: /sk_test_[0-9a-zA-Z]{24,}/g,
    severity: 'high',
    description: 'Stripe test secret key'
  },
  {
    name: 'Anthropic API Key',
    pattern: /sk-ant-[a-zA-Z0-9_-]{50,}/g,
    severity: 'critical',
    description: 'Anthropic API key'
  },
  {
    name: 'OpenAI API Key',
    pattern: /sk-[a-zA-Z0-9]{48}/g,
    severity: 'critical',
    description: 'OpenAI API key'
  },
  {
    name: 'JWT Secret',
    pattern: /jwt[_-]?secret\s*[:=]\s*['"]([^'"]{20,})['"]/gi,
    severity: 'high',
    description: 'JWT secret in code'
  },
  {
    name: 'API Key Generic',
    pattern: /api[_-]?key\s*[:=]\s*['"]([a-zA-Z0-9_-]{20,})['"]/gi,
    severity: 'high',
    description: 'Generic API key'
  },
  {
    name: 'Canary Test Values',
    pattern: /CANARY-[a-zA-Z0-9_-]+/gi,
    severity: 'medium',
    description: 'Canary test credentials (should be in .gitignore)'
  },
  {
    name: 'Base64 Encoded Secret',
    pattern: /['"]([A-Za-z0-9+/]{40,}={0,2})['"]\s*(?:\/\/\s*secret|\/\*\s*secret)/gi,
    severity: 'medium',
    description: 'Possible base64-encoded secret'
  }
];

const IGNORED_DIRECTORIES = [
  'node_modules',
  '.git',
  'dist',
  'build',
  'coverage',
  '.nyc_output'
];

const IGNORED_FILES = [
  '.env.example',
  '.gitignore',
  'package-lock.json',
  'yarn.lock',
  '*.min.js'
];

let findings = [];
let filesScanned = 0;

function shouldIgnore(filePath) {
  const ignores = IGNORED_FILES;

  for (const ignore of ignores) {
    const regex = new RegExp(ignore.replace('*', '.*'));
    if (regex.test(path.basename(filePath))) {
      return true;
    }
  }

  return false;
}

function scanFile(filePath) {
  if (shouldIgnore(filePath)) return;

  try {
    const content = fs.readFileSync(filePath, 'utf8');
    filesScanned++;

    for (const { name, pattern, severity, description } of SECRET_PATTERNS) {
      const matches = content.matchAll(pattern);

      for (const match of matches) {
        const line = content.substring(0, match.index).split('\n').length;

        findings.push({
          file: filePath,
          line,
          secretType: name,
          match: match[0].substring(0, 50) + (match[0].length > 50 ? '...' : ''),
          severity,
          description,
          hash: crypto.createHash('sha256').update(match[0]).digest('hex').substring(0, 8)
        });
      }
    }
  } catch (error) {
    // Skip files that can't be read as text
  }
}

function scanDirectory(dir, recursive = true) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (IGNORED_DIRECTORIES.includes(entry.name)) {
      continue;
    }

    if (entry.isDirectory() && recursive) {
      scanDirectory(fullPath, recursive);
    } else if (entry.isFile() && (entry.name.endsWith('.js') || 
                                    entry.name.endsWith('.json') ||
                                    entry.name.endsWith('.env') ||
                                    entry.name.endsWith('.yml') ||
                                    entry.name.endsWith('.yaml'))) {
      scanFile(fullPath);
    }
  }
}

function generateReport() {
  const severityOrder = { critical: 0, high: 1, medium: 2, low: 3 };
  const sortedFindings = findings.sort((a, b) => severityOrder[a.severity] - severityOrder[b.severity]);

  const severityCounts = {
    critical: sortedFindings.filter(f => f.severity === 'critical').length,
    high: sortedFindings.filter(f => f.severity === 'high').length,
    medium: sortedFindings.filter(f => f.severity === 'medium').length,
    low: sortedFindings.filter(f => f.severity === 'low').length
  };

  console.log('\n' + '='.repeat(70));
  console.log('🔍 SECRET DETECTION REPORT');
  console.log('='.repeat(70));
  console.log(`Files scanned: ${filesScanned}`);
  console.log(`Findings: ${findings.length}`);
  console.log('');

  if (findings.length === 0) {
    console.log('✅ No secrets detected!');
    return 0;
  }

  console.log('Severity breakdown:');
  console.log(`  🔴 CRITICAL: ${severityCounts.critical}`);
  console.log(`  🟠 HIGH:     ${severityCounts.high}`);
  console.log(`  🟡 MEDIUM:   ${severityCounts.medium}`);
  console.log(`  🔵 LOW:      ${severityCounts.low}`);
  console.log('');

  console.log('-'.repeat(70));
  console.log('DETAILED FINDINGS:');
  console.log('-'.repeat(70));

  for (const finding of sortedFindings) {
    const emoji = {
      critical: '🔴',
      high: '🟠',
      medium: '🟡',
      low: '🔵'
    }[finding.severity];

    console.log(`\n${emoji} ${finding.severity.toUpperCase()} - ${finding.secretType}`);
    console.log(`   File: ${finding.file}:${finding.line}`);
    console.log(`   Description: ${finding.description}`);
    console.log(`   Match: ${finding.match}`);
    console.log(`   Hash: ${finding.hash} (for tracking removal)`);
  }

  console.log('\n' + '='.repeat(70));
  console.log('RECOMMENDATIONS:');
  console.log('='.repeat(70));
  console.log('1. Move all secrets to a secrets manager (AWS Secrets Manager) or .env files');
  console.log('2. Remove secrets from git history if committed');
  console.log('3. Rotate any exposed secrets immediately');
  console.log('4. Add .env* to .gitignore');
  console.log('5. Set up pre-commit hooks with secret scanning');
  console.log('');

  if (severityCounts.critical > 0 || severityCounts.high > 0) {
    console.log('⚠️  CRITICAL/HIGH severity issues detected - Immediate action required!');
    return 1;
  }

  console.log('✅ Scan complete');
  return 0;
}

// Main execution
const startDir = process.argv[2] || process.cwd();
console.log(`🔍 Scanning ${startDir} for secrets...`);
console.log('');

try {
  scanDirectory(startDir);
  const exitCode = generateReport();
  process.exit(exitCode);
} catch (error) {
  console.error('Error during scan:', error.message);
  process.exit(1);
}

