```javascript
// secretsManager.js
const AWS = require('aws-sdk');
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManagerClient {
  constructor(region = 'us-east-1') {
    this.client = new SecretsManager({ region });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    if (!forceRefresh && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        console.log(`[SecretsManager] Using cached secret: ${secretName}`);
        return cached.data;
      }
    }

    try {
      console.log(`[SecretsManager] Fetching secret from AWS: ${secretName}`);
      const response = await this.client.getSecretValue({
        SecretId: secretName
      });

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      // Cache the secret
      this.cache.set(secretName, {
        data: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw error;
    }
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = new SecretsManagerClient();
```

