```javascript
// vault.js
const nodeVault = require('node-vault');

class VaultClient {
  constructor(options = {}) {
    this.vault = nodeVault({
      endpoint: options.endpoint || process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
      token: options.token || process.env.VAULT_TOKEN,
    });
    this.cache = new Map();
    this.leaseCache = new Map();
  }

  async getSecret(path) {
    try {
      // Check cache
      if (this.cache.has(path)) {
        const cached = this.cache.get(path);
        return cached;
      }

      const result = await this.vault.read(path);
      const secret = result.data.data;

      // Cache the secret
      this.cache.set(path, secret);

      // Track lease if renewable
      if (result.lease_id) {
        this.leaseCache.set(result.lease_id, {
          path,
          renew: result.renewable,
          ttl: result.lease_duration
        });
      }

      return secret;
    } catch (error) {
      console.error(`[Vault] Failed to get secret ${path}:`, error.message);
      throw error;
    }
  }

  async renewLease(leaseId, increment = '1h') {
    try {
      await this.vault.renew({ lease_id: leaseId, increment });
      console.log(`[Vault] Renewed lease: ${leaseId}`);
    } catch (error) {
      console.error(`[Vault] Failed to renew lease ${leaseId}:`, error.message);
    }
  }

  async clearCache() {
    this.cache.clear();
  }
}

module.exports = new VaultClient();
```

