// In Kubernetes, secrets are injected as environment variables or mounted files

module.exports = {
  // Option A: Environment variables (easiest)
  getEnvSecret: (key) => {
    const value = process.env[key];
    if (!value) {
      throw new Error(`Required secret not found: ${key}`);
    }
    return value;
  },

  // Option B: Mounted secret files (more secure)
  getMountedSecret: (mountPath, secretName) => {
    const fs = require('fs');
    const path = require('path');
    const secretPath = path.join(mountPath, secretName);

    if (!fs.existsSync(secretPath)) {
      throw new Error(`Secret file not found: ${secretPath}`);
    }

    return fs.readFileSync(secretPath, 'utf-8').trim();
  }
};
