```javascript
// parameterStore.js
const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');

class ParameterStoreClient {
  constructor() {
    this.client = new SSMClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
  }

  async getParameter(name, withDecryption = true) {
    const cacheKey = `${name}:${withDecryption}`;

    // Check cache
    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey);
    }

    try {
      const command = new GetParameterCommand({
        Name: name,
        WithDecryption: withDecryption
      });

      const response = await this.client.send(command);
      const value = response.Parameter.Value;

      // Cache the value
      this.cache.set(cacheKey, value);

      return value;
    } catch (error) {
      console.error(`[ParameterStore] Failed to get ${name}:`, error.message);
      throw error;
    }
  }

  async getParametersByPath(path, recursive = true) {
    try {
      const { Parameters } = await this.client.send(
        new GetParametersByPathCommand({
          Path: path,
          Recursive: recursive,
          WithDecryption: true
        })
      );

      const result = {};
      Parameters.forEach(param => {
        const name = param.Name.replace(path, '');
        result[name] = param.Value;
      });

      return result;
    } catch (error) {
      console.error(`[ParameterStore] Failed to get path ${path}:`, error.message);
      throw error;
    }
  }
}

module.exports = new ParameterStoreClient();
