// config/vault.js
const vault = require('node-vault')();

class VaultSecrets {
  constructor(options = {}) {
    this.endpoint = options.endpoint || process.env.VAULT_ADDR || 'http://localhost:8200';
    this.token = options.token || process.env.VAULT_TOKEN;
    this.mount = options.mount || 'secret';
    this.cache = new Map();

    if (this.token) {
      vault.token = this.token;
    }
  }

  async getSecret(path) {
    // Check cache
    if (this.cache.has(`${this.mount}/${path}`)) {
      return this.cache.get(`${this.mount}/${path}`);
    }

    try {
      const result = await vault.read(`${this.mount}/${path}`);
      const secret = result.data.data || result.data;

      // Cache with short TTL
      this.cache.set(`${this.mount}/${path}`, secret);

      return secret;
    } catch (error) {
      throw new Error(`Vault secret retrieval failed: ${error.message}`);
    }
  }

  async getSecretWithRotation(path) {
    // Required for cloud credentials with auto-rotation
    const secret = await this.getSecret(path);

    // If it's cloud credentials, set up renewal if needed
    if (secret.lease_duration) {
      setInterval(async () => {
        try {
          await vault.renew(path);
        } catch (error) {
          console.error('Failed to renew secret lease:', error);
        }
      }, (secret.lease_duration * 0.5) * 1000);
    }

    return secret;
  }
}

module.exports = VaultSecrets;
