// middleware/env-security.js
const fs = require('fs');
const path = require('path');

function validateEnvironmentSecurity() {
  const checks = [];

  // Check for unwanted environment file exposure
  const envFiles = ['.env', '.env.local', '.env.production', '.env.development'];

  envFiles.forEach(filename => {
    const filePath = path.join(process.cwd(), filename);
    if (fs.existsSync(filePath)) {
      const stats = fs.statSync(filePath);
      const mode = stats.mode;

      // Check if file is world-readable
      if (mode & parseInt('0004', 8)) {
        checks.push({
          severity: 'CRITICAL',
          issue: `${filename} is world-readable`,
          fix: `chmod 600 ${filename}`
        });
      }

      // Check if file is group-readable when it shouldn't be
      if (mode & parseInt('0040', 8)) {
        checks.push({
          severity: 'HIGH',
          issue: `${filename} is group-readable`,
          fix: `chmod 600 ${filename}`
        });
      }
    }
  });

  // Check for hardcoded secrets in code
  const sensitivePatterns = [
    /['"]sk_live_[a-zA-Z0-9]{24,}['"]/g, // Stripe live keys
    /['"]AKIA[0-9A-Z]{16}['"]/g, // AWS access keys
    /['"]postgres:\/\/[^'"]+['"]/g, // Database URLs
    /['"]password\s*=\s*['"][^'"]+['"]/g, // Passwords
  ];

  return checks;
}

// Run at startup
const securityChecks = validateEnvironmentSecurity();
if (securityChecks.length > 0) {
