#### Option C: Cloud KMS with Encryption (for smaller deployments)

```javascript
const crypto = require('crypto');

// Encrypt secrets at commit time
function encryptSecret(plaintext, key) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(key, 'hex'), iv);

  let encrypted = cipher.update(plaintext, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag();

  return `${iv.toString('hex')}:${authTag.toString('hex')}:${encrypted}`;
}

// Decrypt at runtime (KMS-encrypted key)
async function decryptSecret(ciphertext, kmsKeyId) {
  const AWS = require('@aws-sdk/client-kms');
  const kms = new AWS.KMSClient({});

  // Decrypt the data key
  const decryptCommand = new AWS.DecryptCommand({
    CiphertextBlob: Buffer.from(kmsKeyId, 'base64')
  });

  const { Plaintext } = await kms.send(decryptCommand);
  const encryptionKey = Plaintext.toString('hex');

  // Decrypt the secret using the data key
  const [ivHex, authTagHex, encrypted] = ciphertext.split(':');
  const decipher = crypto.createDecipheriv(
    'aes-256-gcm',
    Buffer.from(encryptionKey, 'hex'),
    Buffer.from(ivHex, 'hex')
  );

  decipher.setAuthTag(Buffer.from(authTagHex, 'hex'));

  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');

  return decrypted;
}
