# .git/hooks/pre-commit
#!/bin/bash

# Check for .env files in changes
STAGED_FILES=$(git diff --cached --name-only)

if echo "$STAGED_FILES" | grep -qE '\.env|\.env\.local|\.env\.prod'; then
  echo "❌ ERROR: Attempting to commit .env files!"
  echo "   Please remove sensitive files from the commit."
