```javascript
// monitoring/secret-leak-detector.js
const fs = require('fs');
const path = require('path');

const SECRET_PATTERNS = [
  /sk_[a-zA-Z0-9]{20,}/,           // Stripe keys
  /AKIA[0-9A-Z]{16}/,              // AWS access keys
  /Bearer sk-ant-[a-zA-Z0-9-]+/,   // Anthropic API keys
  / postgres:\/\/[^:]+:[^@]+@/,    // Database URLs
  /[a-zA-Z0-9]{32}===/             // Base64-like tokens
];

function scanForSecrets(directory) {
  let foundSecrets = [];

  function scanDir(dir) {
    const files = fs.readdirSync(dir);

    for (const file of files) {
      const filePath = path.join(dir, file);
      const stat = fs.statSync(filePath);

      if (stat.isDirectory() && !file.includes('node_modules')) {
        scanDir(filePath);
      } else if (stat.isFile() && (file.endsWith('.js') || file.endsWith('.json'))) {
        const content = fs.readFileSync(filePath, 'utf8');

        for (const pattern of SECRET_PATTERNS) {
          const matches = content.match(pattern);
          if (matches) {
            foundSecrets.push({ file: filePath, pattern: pattern.source, matches });
          }
        }
      }
    }
  }

  scanDir(directory);
  return foundSecrets;
}

module.exports = { scanForSecrets };

// Run on startup in development
if (process.env.NODE_ENV === 'development') {
  const leaks = scanForSecrets(__dirname);
  if (leaks.length > 0) {
    console.error('🚨 WARNING: Potential secrets detected:');
    leaks.forEach(leak => {
      console.error(`  - ${leak.file}: ${leak.pattern}`);
    });
    process.exit(1);
  }
}
```

