 */
async function loadSecrets() {
  const secretPrefix = process.env.SECRETS_PREFIX || 'prod/myapp';

  const [dbSecret, apiSecrets, paymentSecrets] = await Promise.all([
    getSecret(`${secretPrefix}/database`),
    getSecret(`${secretPrefix}/api`),
    getSecret(`${secretPrefix}/payment`)
