#### Recommended Implementation Pattern:

```javascript
// config/index.js
const { loadSecrets } = require('./secrets');
const { loadParameters } = require('./ssm');

// Only load from .env in development
const IS_DEV = process.env.NODE_ENV !== 'production';

class Config {
  constructor() {
    this.secrets = null;
    this.initialized = false;
  }

  async init() {
    if (this.initialized) return;

    if (IS_DEV) {
      // Use dotenv for development only
      require('dotenv').config({ path: '.env' });
      this.secrets = this.getEnvSecrets();
    } else {
      // Use secrets manager in production
      try {
        this.secrets = await loadSecrets();
      } catch (error) {
        throw new Error(`Failed to load secrets: ${error.message}`);
      }
    }

    this.validateSecrets();
    this.initialized = true;
  }

  getEnvSecrets() {
    return {
      database: {
        url: process.env.DATABASE_URL
      },
      api: {
        anthropic: process.env.ANTHROPIC_API_KEY,
        logfire: process.env.LOGFIRE_TOKEN
      },
      payment: {
        stripe: process.env.STRIPE_SECRET_KEY
      },
      aws: {
        accessKeyId: process.env.AWS_ACCESS_KEY_ID,
        secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        region: process.env.AWS_REGION || 'us-east-1'
      }
    };
  }

  validateSecrets() {
    const required = [
      ['database', 'url'],
      ['api', 'anthropic'],
      ['payment', 'stripe']
    ];

    const missing = required.filter(([section, key]) => {
      return !this.secrets[section]?.[key];
    });

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.map(([s, k]) => `${s}.${k}`).join(', ')}`
      );
    }
  }

  get(path) {
    const keys = path.split('.');
    let value = this.ensureInitialized();

    for (const key of keys) {
      value = value?.[key];
    }

    return value;
  }

  ensureInitialized() {
    if (!this.initialized) {
      throw new Error('Config not initialized. Call init() first.');
    }
    return this.secrets;
  }
}

// Singleton instance
const config = new Config();

module.exports = config;
```

