// Install: npm install @aws-sdk/client-secrets-manager
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, useCache = true) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (useCache && cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName
      });

      const response = await this.client.send(command);
      const secret = response.SecretString;

      // Parse JSON secrets
      const parsedSecret = secret.startsWith('{') ? JSON.parse(secret) : secret;

      // Cache the result
      this.cache.set(secretName, {
        value: parsedSecret,
        timestamp: Date.now()
      });

      return parsedSecret;
    } catch (error) {
      console.error(`Error retrieving secret ${secretName}:`, error.message);
      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  // Multiple Secrets in One Call
  async getSecrets(secretNames) {
    const secrets = {};
    await Promise.all(
      secretNames.map(async (name) => {
        secrets[name] = await this.getSecret(name);
      })
    );
    return secrets;
  }
}

