```javascript
const express = require('express');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const app = express();

// ============== AWS Secrets Manager Configuration ==============

// For local development, can use .env fallback
if (process.env.NODE_ENV === 'development' && !process.env.USE_SECRETS_MANAGER) {
    require('dotenv').config();
}

// Secrets Manager client
const secretsClient = new SecretsManagerClient({
    region: process.env.AWS_REGION || 'us-east-1',
    // For local development with AWS credentials
    ...(process.env.NODE_ENV === 'development' && {
        credentials: {
            accessKeyId: process.env.AWS_ACCESS_KEY_ID,
            secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
            ...(process.env.AWS_SESSION_TOKEN && { 
                sessionToken: process.env.AWS_SESSION_TOKEN 
            })
        }
    })
});

/**
 * Cache secrets with TTL to avoid excessive API calls
 */
const secretsCache = new Map();
const SECRETS_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

/**
 * Retrieve secret from AWS Secrets Manager
 */
async function getSecret(secretName, forceRefresh = false) {
    const cacheKey = secretName;
    const cached = secretsCache.get(cacheKey);

    // Return cached value if still valid
    if (!forceRefresh && cached && (Date.now() - cached.timestamp < SECRETS_CACHE_TTL)) {
        return cached.value;
    }

    try {
        const command = new GetSecretValueCommand({ SecretId: secretName });
        const response = await secretsClient.send(command);

        let secret;
        if (response.SecretString) {
            secret = JSON.parse(response.SecretString);
        } else {
            secret = JSON.parse(Buffer.from(response.SecretBinary, 'base64').toString('utf8'));
        }

        // Cache the secret
        secretsCache.set(cacheKey, {
            value: secret,
            timestamp: Date.now()
        });

        return secret;
    } catch (error) {
        throw new Error(`Failed to retrieve secret "${secretName}": ${error.message}`);
    }
}

/**
 * Load all application secrets at startup
 */
async function loadAppSecrets() {
    const secretNames = [
        'prod/myapp/database',
        'prod/myapp/stripe',
        'prod/myapp/anthropic',
        'prod/myapp/logfire'
    ];

    try {
        const [dbSecret, stripeSecret, anthropicSecret, logfireSecret] = await Promise.all(
            secretNames.map(name => getSecret(name).catch(err => {
                console.warn(`Warning: Failed to load secret ${name}:`, err.message);
                return null;
            }))
        );

        return {
            database: dbSecret,
            stripe: stripeSecret,
            anthropic: anthropicSecret,
            logfire: logfireSecret
        };
    } catch (error) {
        console.error('Failed to load secrets, falling back to environment variables:', error.message);
        return loadSecretsFromEnv();
    }
}

/**
 * Fallback: Load secrets from environment variables
 */
function loadSecretsFromEnv() {
    return {
        database: {
            host: process.env.DB_HOST,
            port: process.env.DB_PORT,
            username: process.env.DB_USERNAME,
            password: process.env.DB_PASSWORD,
            dbname: process.env.DB_NAME
        },
        stripe: {
            secretKey: process.env.STRIPE_SECRET_KEY,
            publishableKey: process.env.STRIPE_PUBLISHABLE_KEY
        },
        anthropic: {
            apiKey: process.env.ANTHROPIC_API_KEY
        },
        logfire: {
            token: process.env.LOGFIRE_TOKEN
        }
    };
}

// ============== Application Initialization ==============

let appSecrets = {};

(async function initializeApp() {
    try {
        console.log('Loading application secrets...');
        appSecrets = await loadAppSecrets();
        console.log('✓ Secrets loaded successfully');

        // Validate critical secrets exist
        if (!appSecrets.stripe?.secretKey) {
            console.warn('⚠ Warning: Stripe secret key not configured');
        }

        // Start server
        const PORT = process.env.PORT || 3000;
        app.listen(PORT, () => {
            console.log(`Server running on port ${PORT}`);
        });
    } catch (error) {
        console.error('Failed to initialize application:', error);
        process.exit(1);
    }
})();

// ============== Routes ==============

app.get('/health', (req, res) => {
    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        // Health check confirms secrets are loaded
        secretsLoaded: !!appSecrets.stripe?.secretKey
    });
});

// Example: Use secrets in a route
app.get('/api/stripe-config', async (req, res) => {
    try {
        // Refresh secret if needed
        if (shouldRefreshSecrets()) {
            appSecrets.stripe = await getSecret('prod/myapp/stripe', true);
        }

        // Only expose non-sensitive data
        res.json({
            enabled: !!appSecrets.stripe?.secretKey,
            mode: appSecrets.stripe?.secretKey?.startsWith('sk_live_') ? 'live' : 'test'
        });
    } catch (error) {
        res.status(500).json({ error: 'Configuration error' });
    }
});

function shouldRefreshSecrets() {
    const cached = secretsCache.get('prod/myapp/stripe');
    return !cached || (Date.now() - cached.timestamp > SECRETS_CACHE_TTL);
}

module.exports = app;
