// secrets-audit.js
const crypto = require('crypto');

function hashSecret(secret) {
  return crypto.createHash('sha256').update(secret).digest('hex');
}

class SecretsAuditor {
  constructor() {
    this.accessLog = [];
  }

  logAccess(secretName, source, userId = 'system') {
    const entry = {
      timestamp: new Date().toISOString(),
      secretName,
      source,
      userId,
      // Hash to confirm which secret without logging the value
      secretHash: hashSecret(process.env[secretName] || '')
    };

    this.accessLog.push(entry);

    // In production, send to audit logging service
    if (process.env.NODE_ENV === 'production') {
      this.sendToAuditLog(entry);
    }
  }

  logRotation(secretName, oldHash, newHash, performedBy) {
    const entry = {
      timestamp: new Date().toISOString(),
      event: 'secret_rotation',
      secretName,
      oldSecretHash: oldHash,
      newSecretHash: newHash,
      performedBy
    };

    this.accessLog.push(entry);
    this.sendToAuditLog(entry);
  }

  sendToAuditLog(entry) {
    // Integration with SIEM or audit logging service
    console.log('[AUDIT]', JSON.stringify(entry));
  }
}

module.exports = new SecretsAuditor();
