// AWS Secrets Manager Integration Example
const AWS = require('aws-sdk');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize Secrets Manager client
const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-west-1'
});

// Cache for secrets to reduce API calls
let secretsCache = null;
let cacheExpiry = null;
const CACHE_TTL = 300000; // 5 minutes

async function getSecrets(secretsNames = [
  'prod/database/prod',
  'prod/aws/credentials',
  'prod/stripe/keys',
  'prod/anthropic/api-key',
  'prod/logfire/token'
]) {
  // Return cached secrets if still valid
  if (secretsCache && cacheExpiry && Date.now() < cacheExpiry) {
    return secretsCache;
  }

  const secrets = {};

  try {
    // Fetch all secrets in parallel
    await Promise.all(secretsNames.map(async (secretName) => {
      try {
        const command = new GetSecretValueCommand({ SecretId: secretName });
        const response = await secretsClient.send(command);

        const secretString = response.SecretString;
        const secretValue = secretString ? JSON.parse(secretString) : {};

        // Merge into secrets object
        Object.assign(secrets, secretValue);
      } catch (error) {
        if (error.name === 'ResourceNotFoundException') {
          console.warn(`Secret not found: ${secretName}`);
        } else {
          console.error(`Error fetching secret ${secretName}:`, error.message);
        }
      }
    }));

    // Cache the secrets
    secretsCache = secrets;
    cacheExpiry = Date.now() + CACHE_TTL;

    return secrets;
  } catch (error) {
    console.error('Failed to fetch secrets:', error);
    throw new Error('Failed to load application secrets');
  }
}

// Example usage in Express app
async function initializeAppWithSecrets(app) {
  try {
    const secrets = await getSecrets();

    // Inject secrets into process.env (or use directly)
    process.env.DATABASE_URL = secrets.database_url;
    process.env.AWS_ACCESS_KEY_ID = secrets.aws_access_key_id;
    process.env.AWS_SECRET_ACCESS_KEY = secrets.aws_secret_access_key;
    process.env.STRIPE_SECRET_KEY = secrets.stripe_secret_key;
    process.env.ANTHROPIC_API_KEY = secrets.anthropic_api_key;
    process.env.LOGFIRE_TOKEN = secrets.logfire_token;

    // Validate required secrets
    const required = ['DATABASE_URL'];
    const missing = required.filter(key => !process.env[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    console.log('✅ Secrets loaded successfully from AWS Secrets Manager');
