// HashiCorp Vault Integration
const axios = require('axios');
const NodeCache = require('node-cache');

// Initialize cache (TTL: 5 minutes)
const secretsCache = new NodeCache({ stdTTL: 300, checkperiod: 60 });

class VaultClient {
  constructor(config = {}) {
    this.vaultUrl = config.url || process.env.VAULT_ADDR || 'http://vault.internal:8200';
    this.role = config.role || process.env.VAULT_ROLE || 'app-role';
    this.secretId = config.secretId || process.env.VAULT_SECRET_ID;
    this.roleId = config.roleId || process.env.VAULT_ROLE_ID;
    this.token = config.token || process.env.VAULT_TOKEN;
    this.namespace = config.namespace || process.env.VAULT_NAMESPACE;
  }

  async getKubernetesAuth() {
    // Use Kubernetes service account for authentication
    const jwt = require('fs').readFileSync('/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8');

    try {
      const response = await axios.post(
        `${this.vaultUrl}/v1/auth/kubernetes/login`,
        {
          role: this.role,
          jwt: jwt,
        },
        {
          headers: { 'X-Vault-Namespace': this.namespace },
        }
      );

      return response.data.auth.client_token;
    } catch (error) {
      console.error('Vault Kubernetes auth failed:', error.message);
      throw error;
    }
  }

  async getAppRoleAuth() {
    // Use AppRole for authentication
    try {
      const response = await axios.post(
        `${this.vaultUrl}/v1/auth/approle/login`,
        {
          role_id: this.roleId,
          secret_id: this.secretId,
        },
        {
          headers: { 'X-Vault-Namespace': this.namespace },
        }
      );

      return response.data.auth.client_token;
    } catch (error) {
      console.error('Vault AppRole auth failed:', error.message);
      throw error;
    }
  }

  async getAuthToken() {
    // Use provided token or authenticate
    if (this.token) {
      return this.token;
    }

    // Try Kubernetes auth first
    try {
      return await this.getKubernetesAuth();
    } catch (error) {
      // Fall back to AppRole
      return await this.getAppRoleAuth();
    }
  }

  async getSecret(path, cacheKey = null) {
    // Check cache first
    if (cacheKey && secretsCache.has(cacheKey)) {
      return secretsCache.get(cacheKey);
    }

    try {
      const token = await this.getAuthToken();

      const response = await axios.get(
        `${this.vaultUrl}/v1/secret/data/${path}`,
        {
          headers: {
            'X-Vault-Token': token,
            'X-Vault-Namespace': this.namespace,
          },
        }
      );

      const secret = response.data.data.data;

      // Cache the secret
      if (cacheKey) {
        secretsCache.set(cacheKey, secret);
      }

      return secret;
    } catch (error) {
      if (error.response?.status === 404) {
        console.warn(`Vault secret not found: ${path}`);
      } else {
        console.error(`Vault getSecret error (${path}):`, error.message);
      }
      throw error;
    }
  }

  async getAllSecrets() {
    const secrets = {};

    try {
      // Load all required secrets
      const paths = {
        database: 'prod/database/production',
        aws: 'prod/aws/credentials',
        stripe: 'prod/stripe/keys',
        anthropic: 'prod/anthropic/api-key',
        logfire: 'prod/logfire/token',
      };

      for (const [key, path] of Object.entries(paths)) {
        secrets[key] = await this.getSecret(path, key);
      }

      console.log('✅ All secrets loaded from Vault');
      return secrets;
    } catch (error) {
      console.error('❌ Failed to load secrets from Vault:', error.message);
      throw error;
    }
  }
}

// Usage example
async function initializeVaultSecrets(app) {
  const vault = new VaultClient();

  try {
    const secrets = await vault.getAllSecrets();

    // Map vault secrets to environment variables
    process.env.DATABASE_URL = secrets.database?.connection_string;
    process.env.AWS_ACCESS_KEY_ID = secrets.aws?.access_key_id;
    process.env.AWS_SECRET_ACCESS_KEY = secrets.aws?.secret_access_key;
    process.env.AWS_SESSION_TOKEN = secrets.aws?.session_token;
    process.env.STRIPE_SECRET_KEY = secrets.stripe?.secret_key;
    process.env.ANTHROPIC_API_KEY = secrets.anthropic?.api_key;
    process.env.LOGFIRE_TOKEN = secrets.logfire?.token;

    return secrets;
  } catch (error) {
    console.error('Vault initialization failed:', error);
    throw error;
  }
}

module.exports = {
  VaultClient,
  initializeVaultSecrets,
};

// Secure .env file handling with validation and encryption
// Use this ONLY for development - never in production!

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class SecureEnvLoader {
  constructor(options = {}) {
    this.envPath = options.path || path.join(process.cwd(), '.env');
    this.requiredVars = options.required || [];
    this.allowMissing = options.allowMissing || false;
    this.encryptionKey = options.encryptionKey || process.env.ENV_ENCRYPTION_KEY;
  }

  /**
   * Validate .env file permissions
   */
  validatePermissions() {
    try {
      const stats = fs.statSync(this.envPath);
      const mode = stats.mode;

      // Check if file is readable by others
      const worldReadable = (mode & 0o004) !== 0;
      const groupReadable = (mode & 0o040) !== 0;

      if (worldReadable || groupReadable) {
        console.warn('⚠️  WARNING: .env file has overly permissive permissions!');

        // Fix permissions automatically
        try {
          fs.chmodSync(this.envPath, 0o600);
          console.log('✅ Fixed permissions to 600 (owner read/write only)');
        } catch (error) {
          console.error('❌ Could not fix permissions:', error.message);
        }
      } else {
        console.log('✅ .env file permissions are correct (600 or stricter)');
      }

      return true;
    } catch (error) {
      console.warn('⚠️  Could not validate .env permissions:', error.message);
      return false;
    }
  }

  /**
   * Decrypt a value (AES-256-GCM)
   */
  decryptValue(encryptedValue) {
    if (!this.encryptionKey) {
      throw new Error('Encryption key not provided via ENV_ENCRYPTION_KEY');
    }

    try {
      const parts = encryptedValue.split(':');
      if (parts.length !== 3) {
        throw new Error('Invalid encrypted value format');
      }

      const [ivHex, authTagHex, ciphertext] = parts;
      const iv = Buffer.from(ivHex, 'hex');
      const authTag = Buffer.from(authTagHex, 'hex');
      const key = crypto.scryptSync(this.encryptionKey, 'salt', 32);

      const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
      decipher.setAuthTag(authTag);

      let decrypted = decipher.update(ciphertext, 'hex', 'utf8');
      decrypted += decipher.final('utf8');

      return decrypted;
    } catch (error) {
      throw new Error(`Decryption failed: ${error.message}`);
    }
  }

  /**
   * Load and parse .env file
   */
  loadEnv() {
    try {
      // Validate permissions first
      this.validatePermissions();

      const envContent = fs.readFileSync(this.envPath, 'utf8');
      const envVars = {};

      // Parse each line
      const lines = envContent.split('\n');

      for (const line of lines) {
        const trimmed = line.trim();

        // Skip empty lines and comments
        if (!trimmed || trimmed.startsWith('#')) {
          continue;
        }

        // Remove inline comments
        const content = trimmed.split('#')[0].trim();

        // Parse KEY=VALUE
        const match = content.match(/^([^=]+)=(.*)$/);
        if (match) {
          const key = match[1].trim();
          let value = match[2].trim();

          // Remove quotes if present
          if ((value.startsWith('"') && value.endsWith('"')) ||
              (value.startsWith("'") && value.endsWith("'"))) {
            value = value.slice(1, -1);
          }

          // Check if value is encrypted (format: iv:tag:ciphertext)
          if (value.includes(':') && value.split(':').length === 3) {
            try {
              value = this.decryptValue(value);
              console.log(`🔓 Decrypted: ${key}`);
            } catch (error) {
              console.warn(`⚠️  Could not decrypt ${key}, using as-is`);
            }
          }

          envVars[key] = value;
        }
      }

      // Validate required variables
      const missing = this.requiredVars.filter(varName => !envVars[varName]);
      if (missing.length > 0 && !this.allowMissing) {
        throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
      }

      // Set in process.env
      for (const [key, value] of Object.entries(envVars)) {
        if (!process.env[key]) {
          process.env[key] = value;
        }
      }

      console.log(`✅ Loaded ${Object.keys(envVars).length} environment variables from .env`);
      return envVars;
    } catch (error) {
      console.error('❌ Failed to load .env:', error.message);
      throw error;
    }
  }

  /**
   * Encrypt a value for use in .env file
   */
  static encryptValue(plaintext, encryptionKey) {
    const iv = crypto.randomBytes(16);
    const key = crypto.scryptSync(encryptionKey, 'salt', 32);

    const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
    let ciphertext = cipher.update(plaintext, 'utf8', 'hex');
    ciphertext += cipher.final('hex');

    const authTag = cipher.getAuthTag();

    return `${iv.toString('hex')}:${authTag.toString('hex')}:${ciphertext}`;
  }
}

// Usage: Secure .env loading for development
async function loadSecureEnv(app) {
  const loader = new SecureEnvLoader({
    path: path.join(process.cwd(), '.env'),
    required: [
      'DATABASE_URL',
      'JWT_SECRET',
    ],
    allowMissing: false,
    encryptionKey: process.env.ENV_ENCRYPTION_KEY,
  });

  try {
    const envVars = loader.loadEnv();
