#### **Approach 1: AWS Secrets Manager (Recommended for Cloud)**

**Prerequisites:**
```bash
npm install @aws-sdk/client-secrets-manager
```

**Implementation:**

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretsClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1'
});

// Cache secrets to avoid excessive API calls
let secretsCache = null;
let cacheExpiry = null;

const getSecret = async (secretName) => {
  // Check cache first (5 minute TTL)
  if (secretsCache && cacheExpiry && Date.now() < cacheExpiry) {
    return secretsCache[secretName];
  }

  try {
    const response = await secretsClient.send(
      new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT'
      })
    );

    const secret = response.SecretString;
    const secretData = JSON.parse(secret);

    // Update cache
    if (!secretsCache || Date.now() >= cacheExpiry) {
      secretsCache = secretData;
      cacheExpiry = Date.now() + (5 * 60 * 1000); // 5 minutes
    }

    return secretData[secretName];
  } catch (error) {
    console.error(`Error retrieving secret ${secretName}:`, error.message);
    throw error;
  }
};

// Preload all secrets at startup (fail fast)
const loadAllSecrets = async () => {
  try {
    const secretsName = process.env.SECRETS_ARN || 'prod/app/secrets';
    const response = await secretsClient.send(
      new GetSecretValueCommand({ SecretId: secretsName })
    );

    return JSON.parse(response.SecretString);
  } catch (error) {
    if (error.name === 'ResourceNotFoundException') {
      console.warn('Secrets not found, falling back to environment variables');
      return null;
    }
    throw error;
  }
};

module.exports = { getSecret, loadAllSecrets };
```

