      };

      // Validate required secrets in production
      if (process.env.NODE_ENV === 'production') {
        const requiredSecrets = ['databaseUrl', 'stripeKey'];
        const missing = requiredSecrets.filter(key => !secrets[key]);
        if (missing.length > 0) {
          throw new Error(`Missing required secrets: ${missing.join(', ')}`);
        }
      }
    }

    console.log('Secrets loaded successfully');
  } catch (error) {
    console.error('Failed to load secrets:', error.message);
    process.exit(1); // Fail fast - don't run without secrets
  }
};

// Start app after secrets are loaded
initializeSecrets().then(() => {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
}).catch((error) => {
  console.error('Failed to initialize:', error);
  process.exit(1);
});

module.exports = app;
