### **Phase 2: Implement AWS Secrets Manager**

```javascript
// config/secrets-manager.js
require('dotenv').config(); // Only for local dev with .env.local not in git

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      // Use IAM role for EC2/ECS, environment variables for local
    });
    this.cache = new Map();
    this.cacheTTL = 300000; // 5 minutes
  }

  async getSecret(secretName, forceRefresh = false) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && !forceRefresh && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secret;
      if (response.SecretString) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      }

      // Cache the result
      this.cache.set(secretName, {
        value: secret,
        timestamp: Date.now()
      });

      return secret;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        throw new Error(`Secret not found: ${secretName}`);
      }
      throw new Error(`Failed to fetch secret: ${error.message}`);
    }
  }

  async getDatabaseUrl() {
    const secret = await this.getSecret('prod/database/credentials');
    return `postgresql://${secret.username}:${secret.password}@${secret.host}:${secret.port}/${secret dbname}`;
  }

  async getAWSCredentials() {
    const secret = await this.getSecret('prod/aws/iam/credentials');
    return {
      accessKeyId: secret.accessKeyId,
      secretAccessKey: secret.secretAccessKey
    };
  }

  async getStripeKey() {
    const secret = await this.getSecret('prod/stripe/api-keys');
    return secret.secretKey;
  }

  async getAnthropicApiKey() {
    const secret = await this.getSecret('prod/anthropic/api-key');
    return secret.apiKey;
  }
}

module.exports = new SecretsManager();
```

