// app.js - SECURE VERSION
require('dotenv').config({ path: '.env.local' }); // Dev only - never commit .env.local

const express = require('express');
const secrets = require('./config/secrets-manager');

const app = express();

// Load secrets securely on startup (fail fast if unavailable)
async function initializeApp() {
  try {
    if (process.env.NODE_ENV === 'production') {
      // Production: Fetch from AWS Secrets Manager
      const [
        dbUrl,
        awsCreds,
        stripeKey,
        anthropicKey
      ] = await Promise.all([
        secrets.getDatabaseUrl(),
        secrets.getAWSCredentials(),
        secrets.getStripeKey(),
        secrets.getAnthropicApiKey()
      ]);

      // Set environment variables (never log them!)
      process.env.DATABASE_URL = dbUrl;
      process.env.AWS_ACCESS_KEY_ID = awsCreds.accessKeyId;
      process.env.AWS_SECRET_ACCESS_KEY = awsCreds.secretAccessKey;
      process.env.STRIPE_SECRET_KEY = stripeKey;
      process.env.ANTHROPIC_API_KEY = anthropicKey;

      console.log('✓ Secrets loaded from AWS Secrets Manager');
    } else {
      // Development: Validate required secrets exist
      const requiredSecrets = [
        'DATABASE_URL', 'STRIPE_KEY', 'ANTHROPIC_API_KEY'
      ];
      const missing = requiredSecrets.filter(s => !process.env[s]);
      if (missing.length > 0) {
        throw new Error(`Missing development secrets: ${missing.join(', ')}`);
      }
      console.log('✓ Development secrets loaded');
    }

    // Start server after secrets are loaded
    app.listen(3000, () => {
      console.log('Server running on port 3000');
    });
  } catch (error) {
    console.error('CRITICAL: Failed to initialize application:', error.message);
    process.exit(1);
  }
}

// Validate secret structure is secure
function validateSecretsConfig() {
  const errors = [];

  // Ensure .env files aren't accidentally committed
  if (process.env.NODE_ENV === 'production') {
    // In production, we SHOULD NOT have .env files loaded
    if (require('fs').existsSync('.env')) {
      errors.push('Production environment has .env file - remove it!');
    }
  }

  if (errors.length > 0) {
    throw new Error(`Security validation failed: ${errors.join('; ')}`);
  }
}

// Secure startup
validateSecretsConfig();
initializeApp();

// 安全地访问密钥的辅助函数 - 在日志中从不记录实际值
function getSecureSecretValue(secretName, value) {
  if (!value) return undefined;

  // 返回带有日志安全的代理对象
  return new Proxy({}, {
    get: (target, prop) => value[prop],
    toString: () => `[REDACTED:${secretName}]`,
    inspect: () => `[REDACTED:${secretName}]`
  });
}

module.exports = app;
