const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const { createLogger, format, transports } = winston;

const app = express();

// =============================================
// SECURITY CONFIGURATION
// =============================================

// Environment validation
requiredEnvVars = ['JWT_SECRET', 'DATABASE_URL'];
const missingVars = requiredEnvVars.filter(v => !process.env[v]);
if (missingVars.length > 0) {
  console.error(`Missing required environment variables: ${missingVars.join(', ')}`);
  process.exit(1);
}

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// CORS configuration
app.use(cors({
  origin: (origin, callback) => {
    const allowedOrigins = process.env.CORS_ORIGINS ? process.env.CORS_ORIGINS.split(',') : [];
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Body parsing with size limits
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: false, limit: '1mb' }));

// =============================================
// LOGGING
// =============================================

const securityLogger = createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: combine(
    format.timestamp(),
    format.json()
  ),
  defaultMeta: { service: 'api' },
  transports: [
    new transports.File({ filename: 'error.log', level: 'error' }),
    new transports.File({ filename: 'security.log', level: 'warn' }),
    new transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  securityLogger.add(new transports.Console({
    format: format.simple()
  }));
}

// Request logging middleware
const requestLogger = (req, res, next) => {
  const startTime = Date.now();

  securityLogger.info('Request received', {
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logData = {
      method: req.method,
      url: req.url,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
    };

    if (res.statusCode >= 400) {
      securityLogger.warn('Request completed with error', logData);
    } else {
      securityLogger.info('Request completed', logData);
    }
  });

  next();
};

app.use(requestLogger);

// =============================================
// RATE LIMITING
// =============================================

const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: { error: 'Too many authentication attempts, please try again later.' },
});

app.use(generalLimiter);

// =============================================
// SECURITY MIDDLEWARE
// =============================================

// HTTPS enforcement in production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure && !req.headers['x-forwarded-proto']) {
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
  }
  next();
});

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  const sanitizeString = (str) => {
    if (typeof str !== 'string') return str;
    return str.trim().replace(/[<>]/g, '');
  };

  const sanitizeObject = (obj) => {
    if (!obj || typeof obj !== 'object') return obj;

    for (const key in obj) {
      if (typeof obj[key] === 'string') {
        obj[key] = sanitizeString(obj[key]);
      } else if (typeof obj[key] === 'object') {
        obj[key] = sanitizeObject(obj[key]);
      }
    }
    return obj;
  };

  if (req.body) req.body = sanitizeObject(req.body);
  if (req.query) req.query = sanitizeObject(req.query);
  if (req.params) req.params = sanitizeObject(req.params);

  next();
};

app.use(sanitizeInput);

// Authentication middleware
const authenticate = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith('Bearer ')) {
      securityLogger.warn('Authentication failed - missing token', { ip: req.ip });
      return res.status(401).json({ error: 'Authentication required' });
    }

    const token = authHeader.slice(7);
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    req.user = decoded;
    securityLogger.info('User authenticated', { userId: decoded.id, ip: req.ip });
    next();
  } catch (err) {
    securityLogger.warn('Authentication failed - invalid token', { 
      ip: req.ip,
      error: err.message 
    });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// Authorization middleware (role-based)
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      securityLogger.warn('Authorization failed', { 
        userId: req.user?.id, 
        userRole: req.user?.role,
        requiredRoles: roles,
        ip: req.ip 
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// Validation middleware
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    securityLogger.warn('Validation failed', { 
      errors: errors.array(),
      body: req.body 
    });
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// =============================================
// API ROUTES WITH VERSIONING
// =============================================

const apiV1 = express.Router();
app.use('/api/v1', apiV1);

// Health check (no auth required)
apiV1.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: '1.0.0' 
  });
});

// Login endpoint
apiV1.post('/login',
  authLimiter,
  [
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 }),
  ],
  validate,
  async (req, res, next) => {
    try {
      const { email, password } = req.body;

      // TODO: Verify credentials against database
      // const user = await authenticateUser(email, password);

      securityLogger.info('Login attempt', { email, ip: req.ip });

      // For demo purposes, reject all logins
      return res.status(401).json({ error: 'Invalid credentials' });

      // On successful auth:
      // const token = jwt.sign(
      //   { id: user.id, email: user.email, role: user.role },
      //   process.env.JWT_SECRET,
      //   { expiresIn: '1h' }
      // );
      // securityLogger.info('User logged in', { userId: user.id, ip: req.ip });
      // res.json({ token, expiresIn: 3600 });

    } catch (err) {
      next(err);
    }
  }
);

// Protected endpoint - Get users (admin only)
apiV1.get('/users',
  authenticate,
  authorize('admin', 'support'),
  async (req, res, next) => {
    try {
      // TODO: Fetch from database with parameterized queries
      securityLogger.info('User list accessed', { 
        accessedBy: req.user.id, 
        ip: req.ip 
      });

      res.json([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ]);
    } catch (err) {
      next(err);
    }
  }
);

// Protected endpoint - Get specific user with validation
apiV1.get('/users/:id',
  authenticate,
  authorize('admin', 'support'),
  [
    param('id').isInt({ min: 1 }).withMessage('ID must be a positive integer')
  ],
  validate,
  async (req, res, next) => {
    try {
      const { id } = req.params;

      securityLogger.info('User detail accessed', { 
        userId: id, 
        accessedBy: req.user.id,
        ip: req.ip 
      });

      // TODO: Fetch from database
      res.json({ id: parseInt(id), name: 'User', email: 'user@example.com' });
    } catch (err) {
      next(err);
    }
  }
);

// Create user (admin only)
apiV1.post('/users',
  authenticate,
  authorize('admin'),
  [
    body('name').trim().isLength({ min: 2, max: 100 }).escape(),
    body('email').isEmail().normalizeEmail(),
    body('role').isIn(['user', 'admin', 'support']).withMessage('Invalid role'),
  ],
  validate,
  async (req, res, next) => {
    try {
      const { name, email, role } = req.body;

      securityLogger.info('User created', { 
        createdEmail: email, 
        createdBy: req.user.id,
        ip: req.ip 
      });

      // TODO: Insert into database with parameterized query
      res.status(201).json({ 
        id: Date.now(), 
        name, 
        email, 
        role,
        createdAt: new Date().toISOString() 
      });
    } catch (err) {
      next(err);
    }
  }
);

// =============================================
// ERROR HANDLING
// =============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  securityLogger.error('Unhandled error', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
  });

  const response = {
    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
  };

  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// =============================================
// SERVER START
// =============================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  securityLogger.info('Server started', { port: PORT, env: process.env.NODE_ENV });
});

module.exports = app;

