/**
 * AWS Secrets Manager Integration
 * 
 * This module provides a secure way to load secrets from AWS Secrets Manager
 * instead of using .env files.
 * 
 * Prerequisites:
 * - AWS credentials configured (IAM role or credentials file)
 * - IAM permission: secretsmanager:GetSecretValue
 * - Secrets already created in Secrets Manager
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Configuration
const SECRETS_PREFIX = 'prod/myapp';
const AWS_REGION = process.env.AWS_REGION || 'us-east-1';

class SecretsManager {
  constructor(region = AWS_REGION) {
    this.client = new SecretsManagerClient({ region });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes cache
  }

  /**
   * Load a single secret from AWS Secrets Manager
   * @param {string} secretName - Name or partial ARN of the secret
   * @returns {Promise<any>} - Parsed secret value (usually JSON)
   */
  async getSecret(secretName) {
    // Check cache first
    const cacheKey = secretName;
    const cached = this.cache.get(cacheKey);
    if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
      console.log(`📦 Using cached secret: ${secretName}`);
      return cached.value;
    }

    try {
      console.log(`🔐 Fetching secret from AWS Secrets Manager: ${secretName}`);

      const command = new GetSecretValueCommand({
        SecretId: secretName,
      });

      const response = await this.client.send(command);

      let secretValue;

      if (response.SecretString) {
        // Secrets are typically stored as JSON
        try {
          secretValue = JSON.parse(response.SecretString);
        } catch {
          secretValue = response.SecretString;
        }
      } else if (response.SecretBinary) {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
      } else {
        throw new Error('Secret has no value');
      }

      // Cache the result
      this.cache.set(cacheKey, {
        value: secretValue,
        timestamp: Date.now(),
        versionId: response.VersionId
      });

      console.log(`✅ Loaded secret: ${secretName} (version: ${response.VersionId})`);
      return secretValue;
    } catch (error) {
      console.error(`❌ Failed to load secret ${secretName}:`, error.message);
      throw error;
    }
  }

  /**
   * Load all secrets with a given prefix
   * @param {string} prefix - Secret name prefix
   * @returns {Promise<Object>} - Map of secret names to values
   */
  async loadAllSecrets(prefix = SECRETS_PREFIX) {
    console.log(`📚 Loading all secrets with prefix: ${prefix}`);

    const secrets = {};

    // List of known secrets (in production, use AWS SDK to list)
    const secretList = [
      `${prefix}/database`,
      `${prefix}/stripe`,
      `${prefix}/api-keys`,
      `${prefix}/jwt`,
    ];

    for (const secretName of secretList) {
      try {
        const value = await this.getSecret(secretName);
        const shortName = secretName.replace(`${prefix}/`, '');
        secrets[shortName] = value;
      } catch (error) {
        if (error.name === 'ResourceNotFoundException') {
          console.warn(`⚠️  Secret not found: ${secretName}`);
        } else {
          throw error;
        }
      }
    }

    return secrets;
  }

  /**
   * Load secrets and set them as environment variables
   * @returns {Promise<void>}
   */
  async loadIntoEnvironment() {
    const secrets = await this.loadAllSecrets();

    // Map secrets to environment variables
    if (secrets.database) {
      const { username, password, host, port, database } = secrets.database;
      process.env.DATABASE_URL = `postgresql://${username}:${password}@${host}:${port}/${database}`;
      process.env.DATABASE_HOST = host;
      process.env.DATABASE_PORT = port;
      process.env.DATABASE_NAME = database;
      process.env.DATABASE_USER = username;
      process.env.DATABASE_PASSWORD = password;
    }

    if (secrets.stripe) {
      process.env.STRIPE_SECRET_KEY = secrets.stripe.secret_key;
      process.env.STRIPE_PUBLISHABLE_KEY = secrets.stripe.publishable_key;
      process.env.STRIPE_WEBHOOK_SECRET = secrets.stripe.webhook_secret;
    }

    if (secrets['api-keys']) {
      process.env.ANTHROPIC_API_KEY = secrets['api-keys'].anthropic_key;
      process.env.LOGFIRE_TOKEN = secrets['api-keys'].logfire_token;
      process.env.SENDGRID_API_KEY = secrets['api-keys'].sendgrid_key;
    }

    if (secrets.jwt) {
      process.env.JWT_SECRET = secrets.jwt.secret;
      process.env.JWT_EXPIRES_IN = secrets.jwt.expires_in || '1h';
    }

    console.log('✅ All secrets loaded into environment variables');
  }

  /**
   * Clear the cache and force reload on next access
   */
  clearCache() {
    this.cache.clear();
    console.log('🧹 Secret cache cleared');
  }

  /**
   * Health check - verify AWS Secrets Manager is accessible
   * @returns {Promise<boolean>}
   */
  async healthCheck() {
    try {
      await this.client.send(new GetSecretValueCommand({
        SecretId: 'does-not-exist-test'
      }));
      return true;
    } catch (error) {
      if (error.name === 'ResourceNotFoundException') {
        // Expected - secret doesn't exist, but we can connect
        return true;
      }
      console.error('❌ AWS Secrets Manager health check failed:', error.message);
      return false;
    }
  }
}

/**
 * Initialize the application with secrets from AWS Secrets Manager
 * This should be called before starting the server
 */
async function initializeSecrets() {
  const secrets = new SecretsManager();

  // Health check
  const isHealthy = await secrets.healthCheck();
  if (!isHealthy) {
    console.error('❌ Cannot connect to AWS Secrets Manager');
    console.error('Falling back to environment variables...');
    return;
  }

  try {
    // Load secrets from AWS Secrets Manager
    await secrets.loadIntoEnvironment();

    // Validate required secrets
    const requiredSecrets = [
      'DATABASE_URL',
      'JWT_SECRET',
    ];

    const missingSecrets = requiredSecrets.filter(
      secret => !process.env[secret]
    );

    if (missingSecrets.length > 0) {
      console.error(`❌ Missing required secrets: ${missingSecrets.join(', ')}`);
      throw new Error('Missing required secrets');
    }

    return secrets;
  } catch (error) {
    console.error('❌ Failed to initialize secrets:', error.message);
    throw error;
  }
}

/**
 * Fallback for local development - load from .env file
 * This should ONLY be used in development/testing, never in production
 */
function loadEnvFile() {
  if (process.env.NODE_ENV === 'production') {
    console.warn('⚠️  WARNING: Attempting to load .env file in production!');
    console.warn('⚠️  This is insecure. Configure AWS Secrets Manager.');
  }

  try {
    require('dotenv').config();
    console.log('📋 Loaded secrets from .env file (development mode only)');
  } catch (error) {
    console.error('⚠️  Failed to load .env file:', error.message);
  }
}

// Export for use in main application
module.exports = {
  SecretsManager,
  initializeSecrets,
  loadEnvFile,
};

// If run directly, perform initialization
if (require.main === module) {
  (async () => {
    console.log('🔐 AWS Secrets Manager Initialization');
    console.log('=====================================\n');

    try {
      const secrets = await initializeSecrets();
      console.log('\n✅ Initialization complete!');
      console.log('\nEnvironment variables set:');
      console.log('  - DATABASE_URL: ✅');
      console.log('  - STRIPE_SECRET_KEY: ✅');
      console.log('  - ANTHROPIC_API_KEY: ✅');
      console.log('  - JWT_SECRET: ✅');
    } catch (error) {
      console.error('\n❌ Initialization failed:', error.message);
      console.error('\nFalling back to .env file...');
      loadEnvFile();
      process.exit(1);
    }
  })();
}

/**
 * Secure Application with AWS Secrets Manager Integration
 * 
 * This is the production-ready version of app.js that:
 * 1. Loads secrets from AWS Secrets Manager (not .env files in production)
 * 2. Validates all required secrets before starting
 * 3. Implements proper error handling
 * 4. Includes fallback for local development
 */

const express = require('express');
const app = express();

// ==========================================
// SECRET MANAGEMENT
// ==========================================

/**
 * Initialize secrets based on environment
 * - Production: Load from AWS Secrets Manager
 * - Development: Load from .env file (only!)
 */
async function initializeSecrets() {
  const env = process.env.NODE_ENV || 'development';

  console.log(`🔐 Loading secrets for environment: ${env}`);

  if (env === 'production') {
    // Load from AWS Secrets Manager
    try {
      const { SecretsManager } = require('@aws-sdk/client-secrets-manager');
      const { getSecretValue } = require('@aws-sdk/client-secrets-manager');

      const client = new SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1',
      });

      const secrets = {
        database: 'prod/myapp/database',
        stripe: 'prod/myapp/stripe', 
        apiKeys: 'prod/myapp/api-keys',
        jwt: 'prod/myapp/jwt',
      };

      // Load each secret
      for (const [key, secretName] of Object.entries(secrets)) {
        try {
          const response = await client.send(
            new getSecretValue({ SecretId: secretName })
          );

          const value = JSON.parse(response.SecretString);

          // Map to environment variables
          if (key === 'database') {
            process.env.DATABASE_URL = `postgresql://${value.username}:${value.password}@${value.host}:${value.port}/${value.database}`;
          } else if (key === 'stripe') {
            process.env.STRIPE_SECRET_KEY = value.secret_key;
            process.env.STRIPE_PUBLISHABLE_KEY = value.publishable_key;
          } else if (key === 'apiKeys') {
            process.env.ANTHROPIC_API_KEY = value.anthropic_key;
            process.env.LOGFIRE_TOKEN = value.logfire_token;
          } else if (key === 'jwt') {
            process.env.JWT_SECRET = value.secret;
            process.env.JWT_EXPIRES_IN = value.expires_in || '1h';
          }

          console.log(`✅ Loaded: ${secretName}`);
        } catch (err) {
          console.error(`❌ Failed to load secret ${secretName}:`, err.message);
          throw err;
        }
      }

      console.log('✅ All secrets loaded from AWS Secrets Manager');

    } catch (error) {
      console.error('❌ Failed to load secrets from AWS Secrets Manager:', error.message);
      console.error('Application cannot start without secrets in production');
      process.exit(1);
    }

  } else {
    // Development/Test: Load from .env file
    console.log('⚠️  Loading secrets from .env file (development mode only)');
    require('dotenv').config({
      path: env === 'test' ? '.env.test' : '.env'
    });
  }

  // Validate required secrets
  const requiredSecrets = ['DATABASE_URL'];
  const missingSecrets = requiredSecrets.filter(s => !process.env[s]);

  if (missingSecrets.length > 0) {
    console.error(`❌ Missing required secrets: ${missingSecrets.join(', ')}`);
    process.exit(1);
  }

  console.log('✅ Secrets initialized successfully\n');
  return true;
}

// ==========================================
// SECURITY MIDDLEWARE
// ==========================================

// Only load these in dependencies are available
let helmet, cors, rateLimit;

try {
  helmet = require('helmet');
  cors = require('cors');
  rateLimit = require('express-rate-limit');
} catch (err) {
  console.warn('⚠️  Security middleware not installed. Run: npm install helmet cors express-rate-limit');
}

// Apply security middleware if available
if (helmet) app.use(helmet());
if (cors) {
  app.use(cors({
    origin: process.env.CORS_ORIGINS?.split(',') || ['http://localhost:3000'],
    credentials: true,
  }));
}
if (rateLimit) {
  app.use(rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,
    message: { error: 'Too many requests' }
  }));
}

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.url}`);
  next();
});

// ==========================================
// EXAMPLE API ROUTES
// ==========================================

// Health check (no auth required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    secretsSource: process.env.NODE_ENV === 'production' ? 'AWS Secrets Manager' : '.env file'
  });
});

// Public endpoint
app.get('/public', (req, res) => {
  res.json({ message: 'Public endpoint - no authentication required' });
});

// Protected endpoint example (would require auth in production)
app.get('/users', (req, res) => {
  // In production, add authentication middleware here
  // Example: app.get('/users', authenticate, authorize('admin'), ...)

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ==========================================
// ERROR HANDLING
// ==========================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);

  const isDev = process.env.NODE_ENV !== 'production';
  res.status(err.status || 500).json({
    error: isDev ? err.message : 'Internal server error',
    ...(isDev && { stack: err.stack })
  });
});

// ==========================================
// SERVER STARTUP
// ==========================================

const PORT = process.env.PORT || 3000;

/**
 * Start the application
 */
async function startServer() {
  try {
    // Initialize secrets first
    await initializeSecrets();

    // Start server
    app.listen(PORT, () => {
      console.log('==============================================');
      console.log(`🚀 Server running on port ${PORT}`);
      console.log(`🌍 Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`🔐 Secrets source: ${process.env.NODE_ENV === 'production' ? 'AWS Secrets Manager' : '.env file'}`);
      console.log(`📊 Health check: http://localhost:${PORT}/health`);
      console.log('==============================================');
    });

  } catch (error) {
    console.error('❌ Failed to start server:', error);
    process.exit(1);
  }
}

// Only start server if this file is run directly
if (require.main === module) {
  startServer();
}

module.exports = { app, initializeSecrets };

