 */
function getSecretsNeedingRotation(asOfDate = new Date()) {
  const overdue = [];
  const upcoming = [];

  Object.entries(SECRETS_REGISTRY).forEach(([name, config]) => {
    if (!config.nextRotationDue) return;

    const dueDate = new Date(config.nextRotationDue);
    if (dueDate < asOfDate) {
