// config/secrets.js - Secure secrets loading
require('dotenv').config({ path: '.env.local' }); // Never commit .env.local

const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

class SecretsManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretName, useCache = true) {
    const cached = this.cache[secretName];
    if (useCache && cached && Date.now() - cached.timestamp < this.cacheTTL) {
      return cached.value;
    }

    try {
      const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();
      const secret = data.SecretString;

      if (secret) {
        this.cache[secretName] = { value: JSON.parse(secret), timestamp: Date.now() };
        return this.cache[secretName].value;
      }
    } catch (error) {
      console.error(`Failed to fetch secret ${secretName}:`, error.message);

      // Fallback to environment variables in non-production
      if (process.env.NODE_ENV !== 'production') {
        console.warn(`Using environment variable fallback for ${secretName}`);
        return process.env[secretName];
      }
      throw error;
    }
  }
}

module.exports = new SecretsManager();
