### 🟢 Production-Grade Solution: Secrets Manager

#### AWS Secrets Manager
```javascript
// secrets/secrets-manager.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({ region: process.env.AWS_REGION });

async function getSecret(secretName) {
  try {
    const data = await client.getSecretValue({ SecretId: secretName }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    }

    // Handle binary secrets
    const buff = Buffer.from(data.SecretBinary, 'base64');
    return buff.toString('ascii');

  } catch (err) {
    console.error(`Error retrieving secret ${secretName}:`, err);
    throw err;
  }
}

// Cache secrets in memory to reduce API calls
let secretsCache = {};

async function loadSecrets() {
  if (Object.keys(secretsCache).length > 0) {
    return secretsCache;
  }

  const secretNames = [
    'prod/database/credentials',
    'prod/jwt/secret',
    'prod/stripe/keys',
    'prod/api/keys'
  ];

  for (const name of secretNames) {
    secretsCache[name] = await getSecret(name);
  }

  return secretsCache;
}

module.exports = { getSecret, loadSecrets };
```

#### Usage in app.js
```javascript
const { loadSecrets } = require('./secrets/secrets-manager');

async function startServer() {
  try {
    // Load secrets from AWS Secrets Manager
    const secrets = await loadSecrets();

    const app = express();

    // Use loaded secrets
    app.set('dbUrl', secrets['prod/database/credentials'].url);
    app.set('jwtSecret', secrets['prod/jwt/secret'].value);

    app.listen(3000, () => {
      console.log('Server started with loaded secrets');
    });

  } catch (err) {
    console.error('Failed to load secrets:', err);
    process.exit(1);
  }
}

startServer();
```

